#pragma once
#include "drive.hpp"
#include <array>

namespace bridge::files::rdpdr {
inline constexpr std::size_t maximum_transfer_bytes = 1024 * 1024;
inline constexpr std::size_t maximum_request_bytes = maximum_transfer_bytes + 32;
inline constexpr std::size_t maximum_reply_bytes = maximum_transfer_bytes + 4;
inline constexpr std::uint32_t managed_io_mask = 0x00001d1d;
// Narrow only client GENERAL/DRIVE capability PDUs generated by the pinned SDK.
// Parse completely before mutation; no allocations or added peer capabilities.
bool restrict_capabilities(::bridge::compat::span<std::uint8_t>) noexcept;
// SDK SVC reassembly must be guarded BEFORE it allocates its advertised size.
// This scalar admission state owns no payload buffer or queue.
class Ingress {
  std::size_t total_ = 0, received_ = 0, fragments_ = 0;
  std::uint64_t last_ = 0, deadline_ = 0;
  bool clocked_ = false, active_ = false, failed_ = false, closed_ = false;
  bool fail() noexcept;

public:
  bool poll(std::uint64_t now_ms) noexcept;
  bool admit(std::size_t size, std::size_t total, bool first, bool last, std::uint64_t now_ms) noexcept;
  void close() noexcept;
};
// Wire constants are checked against the pinned public WinPR headers by the
// linked adapter tests. This codec remains usable in the foundation/fuzz build.
enum class NtStatus : std::uint32_t {
  success = 0, no_more_files = 0x80000006, unsuccessful = 0xc0000001,
  invalid_handle = 0xc0000008, invalid_parameter = 0xc000000d,
  no_such_file = 0xc000000f, end_of_file = 0xc0000011,
  access_denied = 0xc0000022, name_collision = 0xc0000035,
  sharing_violation = 0xc0000043, delete_pending = 0xc0000056,
  disk_full = 0xc000007f, device_not_ready = 0xc00000a3,
  is_directory = 0xc00000ba, not_supported = 0xc00000bb,
  directory_not_empty = 0xc0000101, not_directory = 0xc0000103,
  too_many_open_files = 0xc000011f,
};
struct Reply {
  NtStatus status = NtStatus::success;
  std::vector<std::uint8_t> bytes;
  bool malformed = false; // C adapter must discard this IRP and fail the channel.
};
NtStatus status(DriveStatus) noexcept;
// Path is little-endian UTF-16. One optional virtual-root separator is stripped;
// UNC/drive letters, malformed Unicode, traversal and stream/device names fail.
std::optional<std::string> path(::bridge::compat::span<const std::uint8_t>, bool terminated);

// One synchronous device view; engine owns the shared per-session handle table.
// No receive queue. Caller serializes calls and joins them before close/destruct.
class Wire {
  struct Enumeration {
    std::uint32_t handle = 0;
    NativeFileId after = 0, entry = 0;
    std::string pattern;
    std::string directory_path;
    bool started = false, exhausted = false;
    bool xrdp_unused_mkdir = false, xrdp_legacy_delete = false;
  };
  DriveSession &engine_;
  const std::size_t share_;
  using Enumerations = std::array<Enumeration, 128>;
  std::unique_ptr<Enumerations> enumerations_ = std::make_unique<Enumerations>();
  bool closed_ = false;
  Enumeration *enumeration(std::uint32_t) noexcept;
  Reply perform(std::uint32_t major, std::uint32_t minor, std::uint32_t handle,
                ::bridge::compat::span<const std::uint8_t>);

public:
  Wire(DriveSession &, std::size_t share);
  ~Wire();
  Wire(const Wire &) = delete;
  Wire &operator=(const Wire &) = delete;
  Reply request(std::uint32_t major, std::uint32_t minor, std::uint32_t handle,
                ::bridge::compat::span<const std::uint8_t>);
  void close();
};
} // namespace bridge::files::rdpdr
